# owner: platform
"""Lay students out in seating rows."""

from rosterkit.errors import ProjectError


def _name_key(student):
    return (student.last_name.lower(), student.first_name.lower())


def _chunk(items, size):
    return [items[at:at + size] for at in range(0, len(items), size)]


def _row_line(number, row):
    names = " | ".join(item.display_name for item in row)
    return f"Row {number}: {names}"


# ---
def seat_rows(students, seats):
    if seats <= 0 or not students:
        raise ProjectError("need students and a seat count")
    ordered = sorted(students, key=_name_key)
    rows = _chunk(ordered, seats)
    return list(map(_row_line, range(1, len(rows) + 1), rows))
EOF
cat > tests/test_seating.py <<'EOF'
# owner: platform
import unittest

from rosterkit.errors import ProjectError
from rosterkit.models import Student
from rosterkit.seating import seat_rows


def _make(last, first):
    return Student("id", last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        people = [
            _make("Halloway", "Juno"),
            _make("Dunmere", "Piet"),
            _make("Aldous", "Wren")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Aldous, Wren | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count(self):
        people = [_make("Dunmere", "Piet")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seat_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
EOF
